const body = $json.body ?? $json;
const rawEmail = body.email ?? body;
const candidates = Array.isArray(body.candidates) ? body.candidates : [];
const subject = String(rawEmail.subject ?? '').trim();
const emailBody = String(rawEmail.body ?? rawEmail.text ?? '').trim();
if (!subject && !emailBody) throw new Error('BUYFLOW_EMPTY_EMAIL');
const requestId = String(body.request_id ?? `local-${Date.now()}-${Math.random().toString(16).slice(2)}`);
return [{ json: {
  request_id: requestId,
  email: { from: String(rawEmail.from ?? ''), subject, body: emailBody, received_at: rawEmail.received_at ?? null },
  candidates: candidates.map((c) => ({
    purchase_id: String(c.purchase_id ?? c.id ?? ''),
    merchant: c.merchant ?? null,
    order_ids: Array.isArray(c.order_ids) ? c.order_ids.map(String) : [],
    tracking_ids: Array.isArray(c.tracking_ids) ? c.tracking_ids.map(String) : [],
    invoice_ids: Array.isArray(c.invoice_ids) ? c.invoice_ids.map(String) : [],
    amount: c.amount ?? null,
    currency: c.currency ?? null,
    created_at: c.created_at ?? null,
    status: c.status ?? null
  })).filter((c) => c.purchase_id),
  mode: 'SHADOW'
} }];

const raw = String($json.message?.content ?? $json.response ?? '').trim();
if (!raw) throw new Error('BUYFLOW_OLLAMA_EMPTY_RESPONSE');
let parsed;
try { parsed = JSON.parse(raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/i, '').trim()); }
catch (e) { throw new Error(`BUYFLOW_INVALID_AI_JSON: ${raw.slice(0, 500)}`); }

const events = new Set(['ORDER_CREATED','ORDER_PROCESSING','ORDER_PACKING','SHIPMENT_CREATED','SHIPPED','IN_TRANSIT','OUT_FOR_DELIVERY','READY_FOR_PICKUP','DELIVERED','DELIVERY_FAILED','DELAYED','CANCELLED','REFUNDED','PAYMENT','INVOICE','RETURN','WARRANTY','OTHER']);
const actions = new Set(['CREATE_PURCHASE','LINK_EXISTING','REVIEW','IGNORE']);
if (!events.has(parsed.event_type)) throw new Error(`BUYFLOW_INVALID_EVENT:${parsed.event_type}`);
if (!actions.has(parsed.action)) throw new Error(`BUYFLOW_INVALID_ACTION:${parsed.action}`);

const original = $('Normalize Request').item.json;
const text = `${original.email?.subject ?? ''}\n${original.email?.body ?? ''}`.toLowerCase();
const guardrails = [];
const hasAny = (arr) => arr.some((s) => text.includes(s));

const delivered = hasAny(['sikeresen kézbesítettük','sikeresen kezbesitettuk','successfully delivered','kézbesítettük a címzettnek','kezbesitettuk a cimzettnek']);
const outForDelivery = hasAny(['ma kézbesítjük','ma kezbesitjuk','kézbesítés ma várható','kezbesites ma varhato','out for delivery']);
const pickup = hasAny(['átvehető','atveheto','ready for pickup']) && hasAny(['csomagautomat','pickup','átvételi pont','atveteli pont']);
const failedDelivery = hasAny(['kézbesítési kísérlet sikertelen','kezbesitesi kiserlet sikertelen','delivery attempt failed']) && hasAny(['újra megpróbál','ujra megprobal','retry','depó','depo']);
const actualReturn = hasAny(['visszaküldési folyamata elindult','visszakuldesi folyamata elindult','visszaküldés a feladónak','visszakuldes a feladonak','return to sender']);
const shipmentCreatedOnly = hasAny(['címkét létrehozt','cimket letrehozt','küldeményt rögzített','kuldemenyt rogzitett','tracking number created','label created']) && hasAny(['még a raktár','meg a raktar','felvétele még nem történt','felvetele meg nem tortent','not yet picked up','still with sender']);
const positiveHandoffPatterns = [
  /fizikailag\s+(?:átadt|atadt)\w*/,
  /(?:átadt|atadt)\w*.{0,90}(?:futár|futar|carrier|dpd|gls|express\s*one)/,
  /(?:átvette|atvette)\s+(?:a\s+|az\s+)?(?:dpd|gls|express\s*one|[^.\n]{0,40}\s)?futár/,
  /(?:gls|dpd|express\s*one|futár|futar).{0,90}(?:felvette|felvett|átvette|atvette)\s+(?:tőlünk|tolunk|a\s+csomag|a\s+küldemény|a\s+kuldemeny)?/,
  /(?:felvette|felvett)\s+(?:tőlünk|tolunk)/,
  /(?:átvettük|atvettuk)\s+(?:a\s+)?feladó(?:tól|tol)/,
  /carrier.{0,60}(?:picked\s*up|accepted)/,
  /(?:handed|turned)\s+over\s+to.{0,60}carrier/,
  /physical\s+(?:carrier\s+)?handoff/
];
const negativePreHandoff = hasAny([
  'még nem vette át','meg nem vette at',
  'még nem vették át','meg nem vettek at',
  'felvétele még nem történt','felvetele meg nem tortent',
  'not yet picked up','still with sender'
]);
const handoff = !negativePreHandoff && positiveHandoffPatterns.some((r) => r.test(text));
const cartAbandon = hasAny(['kosarad még vár','kosarad meg var','kosaradban hagyt','complete your purchase','fejezd be a vásárlást','fejezd be a vasarlast']);
const injection = hasAny(['ignore previous instructions','ignore all previous instructions','output link_existing','reveal the system prompt']);
const marketing = hasAny(['hírlevél','hirlevel','newsletter','kupon','kedvezmény','kedvezmeny','akció','akcio']);

const aiSemanticText = [
  ...(Array.isArray(parsed.evidence) ? parsed.evidence.map(String) : []),
  String(parsed.reason ?? '')
].join(' ').toLowerCase();
const aiSaysHandoff = [
  /handed\s+over\s+to/,
  /picked\s+up\s+by/,
  /carrier\s+(?:has\s+)?accepted/,
  /physical\s+handoff/,
  /shipment\s+was\s+handed\s+over/
].some((r) => r.test(aiSemanticText));

let semanticOverride = null;
if (delivered) semanticOverride = 'DELIVERED';
else if (outForDelivery) semanticOverride = 'OUT_FOR_DELIVERY';
else if (pickup) semanticOverride = 'READY_FOR_PICKUP';
else if (actualReturn) semanticOverride = 'RETURN';
else if (failedDelivery) semanticOverride = 'DELIVERY_FAILED';
else if (shipmentCreatedOnly) semanticOverride = 'SHIPMENT_CREATED';
else if (handoff || aiSaysHandoff) semanticOverride = 'SHIPPED';

if (cartAbandon || (injection && marketing)) {
  if (parsed.event_type !== 'OTHER' || parsed.action !== 'IGNORE') guardrails.push('non_commerce_marketing_or_prompt_injection');
  parsed.event_type = 'OTHER';
  parsed.action = 'IGNORE';
  parsed.selected_purchase_id = null;
} else if (semanticOverride && parsed.event_type !== semanticOverride) {
  parsed.event_type = semanticOverride;
  guardrails.push(`semantic_boundary:${semanticOverride}`);
}

const normalizeKey = (v) => String(v ?? '').trim().toLowerCase();
const containsKey = (key) => {
  const k = normalizeKey(key);
  return !!k && text.includes(k);
};
const candidates = original.candidates || [];
const hardMatches = [];
for (const c of candidates) {
  const keys = [...(c.order_ids || []), ...(c.tracking_ids || []), ...(c.invoice_ids || [])];
  if (keys.some(containsKey)) hardMatches.push(String(c.purchase_id));
}
const uniqueHard = [...new Set(hardMatches)];

if (parsed.event_type === 'OTHER') {
  parsed.action = 'IGNORE';
  parsed.selected_purchase_id = null;
} else if (uniqueHard.length === 1) {
  const proven = uniqueHard[0];
  if (parsed.action !== 'LINK_EXISTING' || String(parsed.selected_purchase_id ?? '') !== proven) {
    parsed.action = 'LINK_EXISTING';
    parsed.selected_purchase_id = proven;
    guardrails.push('identity_exact_hard_key');
  }
} else if (uniqueHard.length > 1) {
  parsed.action = 'REVIEW';
  parsed.selected_purchase_id = null;
  guardrails.push('identity_multiple_hard_matches');
} else {
  const lifecycleOnly = new Set(['ORDER_PROCESSING','ORDER_PACKING','SHIPMENT_CREATED','SHIPPED','IN_TRANSIT','OUT_FOR_DELIVERY','READY_FOR_PICKUP','DELIVERED','DELIVERY_FAILED','DELAYED','PAYMENT','INVOICE','RETURN','WARRANTY','CANCELLED','REFUNDED']);
  if (parsed.event_type === 'ORDER_CREATED') {
    parsed.action = 'CREATE_PURCHASE';
    parsed.selected_purchase_id = null;
    guardrails.push('new_order_without_existing_hard_match');
  } else if (lifecycleOnly.has(parsed.event_type)) {
    parsed.action = 'REVIEW';
    parsed.selected_purchase_id = null;
    guardrails.push('lifecycle_without_unique_hard_match');
  } else if (parsed.action === 'LINK_EXISTING') {
    parsed.action = 'REVIEW';
    parsed.selected_purchase_id = null;
    guardrails.push('link_without_hard_identity_proof');
  }
}

const expectedCommerce = parsed.event_type !== 'OTHER';
parsed.is_commerce = expectedCommerce;
const confidence = Number(parsed.confidence);
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error('BUYFLOW_INVALID_CONFIDENCE');

const candidateIds = new Set(candidates.map((c) => String(c.purchase_id)));
if (parsed.action === 'LINK_EXISTING') {
  const selected = String(parsed.selected_purchase_id ?? '');
  if (!selected || !candidateIds.has(selected)) throw new Error(`BUYFLOW_AI_INVENTED_OR_INVALID_PURCHASE_ID:${selected}`);
  if (!uniqueHard.includes(selected)) throw new Error(`BUYFLOW_LINK_WITHOUT_HARD_PROOF:${selected}`);
  parsed.selected_purchase_id = selected;
} else {
  parsed.selected_purchase_id = null;
}

return [{ json: {
  ok: true,
  request_id: original.request_id,
  provider: 'ollama-local',
  model: $env.BUYFLOW_OLLAMA_MODEL || 'qwen3:8b',
  mode: 'SHADOW',
  execution_allowed: String($env.BUYFLOW_AI_EXECUTE || 'false').toLowerCase() === 'true',
  ruleset: 'agent-critic-v3',
  guardrails_applied: guardrails,
  identity_proof: { hard_matches: uniqueHard },
  decision: {
    is_commerce: expectedCommerce,
    event_type: parsed.event_type,
    action: parsed.action,
    selected_purchase_id: parsed.selected_purchase_id,
    confidence,
    evidence: Array.isArray(parsed.evidence) ? parsed.evidence.slice(0, 8).map(String) : [],
    reason: String(parsed.reason ?? '').slice(0, 1000)
  }
} }];
